[workspace]
resolver = "2"
default-members = [
    "rust/perspective",
    "rust/perspective-client",
    "rust/perspective-js",
    "rust/perspective-python",
    "rust/perspective-server",
    "rust/perspective-viewer",
]
members = [
    "rust/lint",
    "rust/metadata",
    "rust/bundle",
    "rust/perspective",
    "rust/perspective-client",
    "rust/perspective-js",
    "rust/perspective-migrate",
    "rust/perspective-python",
    "rust/perspective-server",
    "rust/perspective-viewer",
    "examples/rust-axum",
]

[profile.dev]
panic = "abort"
opt-level = 2

[profile.release]
panic = "abort"
opt-level = "z"
codegen-units = 1
lto = true
strip = true

[profile.release.package]
calendrical_calculations = { opt-level = 3 }
core_maths = { opt-level = 3 }
fixed_decimal = { opt-level = 3 }
icu_calendar = { opt-level = 3 }
icu_datetime = { opt-level = 3 }
icu_decimal = { opt-level = 3 }
icu_experimental = { opt-level = 3 }
icu_locale_core = { opt-level = 3 }
icu_pattern = { opt-level = 3 }
icu_plurals = { opt-level = 3 }
icu_provider = { opt-level = 3 }
icu_time = { opt-level = 3 }
libm = { opt-level = 3 }
litemap = { opt-level = 3 }
potential_utf = { opt-level = 3 }
ryu = { opt-level = 3 }
smallvec = { opt-level = 3 }
tinystr = { opt-level = 3 }
writeable = { opt-level = 3 }
yoke = { opt-level = 3 }
zerofrom = { opt-level = 3 }
zerotrie = { opt-level = 3 }
zerovec = { opt-level = 3 }

[profile.fast]
inherits = "release"
opt-level = "s"
codegen-units = 256
lto = "off"
incremental = true

# These are only respected when `cargo` is invoked from the project root
[patch.crates-io]
# simd-adler32 = { git = "https://github.com/mcountryman/simd-adler32.git", rev = "b279034d9eb554c3e5e0af523db044f08d8297ba" }
protobuf-src = { git = "https://github.com/carlocorradini/rust-protobuf-native.git", rev = "1aba500e469f8bdc384a0fe9e69c189fda72e059" }
perspective-client = { path = "rust/perspective-client" }
perspective-server = { path = "rust/perspective-server" }
perspective-js = { path = "rust/perspective-js" }
perspective-migrate = { path = "rust/perspective-migrate" }
perspective = { path = "rust/perspective" }
perspective-viewer = { path = "rust/perspective-viewer" }
perspective-python = { path = "rust/perspective-python" }

{
  "name": "pstack",
  "private": true,
  "version": "0.9.153",
  "description": "If you want to go fast, go deep first. pstack helps you write less, but higher quality code. rigorous agent workflows you can parallelize with confidence. Pi and OpenCode package of the Claude Code plugin; skills are shared, and runtime mappings translate tool names. Original pstack by Lauren Tan (poteto).",
  "author": {
    "name": "Michael Denyer",
    "url": "https://github.com/michael-denyer"
  },
  "homepage": "https://github.com/michael-denyer/pstack-claude",
  "repository": "https://github.com/michael-denyer/pstack-claude",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "pstack",
    "poteto-mode",
    "workflow",
    "principles",
    "agent-style",
    "subagents",
    "unslop",
    "claude-code",
    "skills",
    "tdd",
    "code-review",
    "parallel-agents",
    "codex",
    "opencode",
    "gemini-cli",
    "prime-agent"
  ],
  "pi": {
    "skills": [
      "./plugins/pstack/skills"
    ],
    "extensions": [
      "./plugins/pstack/pi/index.ts"
    ]
  },
  "exports": {
    "./server": "./plugins/pstack/opencode/index.js"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  }
}

{
  "name": "@openai/codex-plugin-cc",
  "version": "1.0.6",
  "private": true,
  "type": "module",
  "description": "Use Codex from Claude Code to review code or delegate tasks.",
  "license": "Apache-2.0",
  "engines": {
    "node": ">=18.18.0"
  },
  "scripts": {
    "bump-version": "node scripts/bump-version.mjs",
    "check-version": "node scripts/bump-version.mjs --check",
    "prebuild": "mkdir -p plugins/codex/.generated/app-server-types && codex app-server generate-ts --out plugins/codex/.generated/app-server-types",
    "build": "tsc -p tsconfig.app-server.json",
    "test": "node --test tests/*.test.mjs"
  },
  "devDependencies": {
    "@types/node": "^25.5.0",
    "typescript": "^6.0.2"
  }
}
